import React, { useState, useRef, useEffect } from 'react';
import { MapContainer, TileLayer, Marker, Popup, useMap } from 'react-leaflet';
import L from 'leaflet';
import 'leaflet/dist/leaflet.css';

// Fix for default marker icons in react-leaflet
delete L.Icon.Default.prototype._getIconUrl;
L.Icon.Default.mergeOptions({
  iconRetinaUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.7.1/images/marker-icon-2x.png',
  iconUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.7.1/images/marker-icon.png',
  shadowUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.7.1/images/marker-shadow.png'
});

// Map controller component to handle map interactions
const MapController = ({ onMapClick, initialLocation }) => {
  const map = useMap();

  useEffect(() => {
    if (!map) return;

    const handleMapClick = (e) => {
      onMapClick({
        latitude: e.latlng.lat,
        longitude: e.latlng.lng
      });
    };

    map.on('click', handleMapClick);

    return () => {
      map.off('click', handleMapClick);
    };
  }, [map, onMapClick]);

  return null;
};

const LocationPicker = ({ onLocationSelect, initialLat = 23.8103, initialLng = 90.4167 }) => {
  const [location, setLocation] = useState({
    latitude: initialLat,
    longitude: initialLng
  });
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const mapRef = useRef(null);

  // Update parent component when location changes
  useEffect(() => {
    onLocationSelect(location);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [location]);

  const handleMapClick = (newLocation) => {
    setLocation(newLocation);
    setError('');
  };

  const handleUseCurrentLocation = () => {
    setLoading(true);
    setError('');

    if (!navigator.geolocation) {
      setError('Geolocation is not supported by your browser');
      setLoading(false);
      return;
    }

    navigator.geolocation.getCurrentPosition(
      (position) => {
        const { latitude, longitude } = position.coords;
        setLocation({
          latitude,
          longitude
        });
        setLoading(false);
      },
      (err) => {
        console.error('Geolocation error:', err);
        if (err.code === 1) {
          setError('Location access denied. Please enable location permissions.');
        } else if (err.code === 2) {
          setError('Location unavailable. Please try again.');
        } else {
          setError('Failed to get your location. Please try again.');
        }
        setLoading(false);
      },
      {
        enableHighAccuracy: true,
        timeout: 10000,
        maximumAge: 0
      }
    );
  };

  return (
    <div className="w-full space-y-4">
      {/* Map Container */}
      <div className="relative rounded-xl overflow-hidden shadow-lg border-2 border-gray-200">
        <div className="h-96 w-full bg-gray-100">
          <MapContainer
            ref={mapRef}
            center={[location.latitude, location.longitude]}
            zoom={14}
            style={{ height: '100%', width: '100%' }}
            className="z-0"
          >
            <TileLayer
              url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
              attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
            />
            <MapController onMapClick={handleMapClick} initialLocation={location} />
            <Marker position={[location.latitude, location.longitude]}>
              <Popup>
                <div className="text-sm font-semibold">
                  <p>Selected Location</p>
                  <p className="text-xs text-gray-600">
                    {location.latitude.toFixed(4)}, {location.longitude.toFixed(4)}
                  </p>
                </div>
              </Popup>
            </Marker>
          </MapContainer>
        </div>
        <div className="absolute top-4 left-4 z-10 bg-white rounded-lg shadow-lg p-4 max-w-xs">
          <p className="text-sm font-semibold text-gray-800 mb-2">📍 Crime Location</p>
          <p className="text-xs text-gray-600">
            Latitude: <span className="font-mono font-semibold">{location.latitude.toFixed(6)}</span>
          </p>
          <p className="text-xs text-gray-600">
            Longitude: <span className="font-mono font-semibold">{location.longitude.toFixed(6)}</span>
          </p>
          <p className="text-xs text-gray-500 mt-2">Click on the map to select a location</p>
        </div>
      </div>

      {/* Error Message */}
      {error && (
        <div className="bg-red-50 border-2 border-red-200 text-red-800 px-4 py-3 rounded-lg text-sm flex items-start gap-2">
          <svg className="w-5 h-5 flex-shrink-0 mt-0.5" fill="currentColor" viewBox="0 0 24 24">
            <path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm1 15h-2v-2h2v2zm0-4h-2V7h2v6z" />
          </svg>
          <span>{error}</span>
        </div>
      )}

      {/* GPS Button */}
      <button
        onClick={handleUseCurrentLocation}
        disabled={loading}
        className="w-full bg-gradient-to-r from-blue-600 to-blue-700 hover:from-blue-700 hover:to-blue-800 disabled:from-gray-400 disabled:to-gray-500 text-white font-semibold py-3 px-4 rounded-lg transition-all duration-200 flex items-center justify-center gap-2 shadow-md hover:shadow-lg"
      >
        {loading ? (
          <>
            <svg className="animate-spin w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
              <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
            </svg>
            Getting your location...
          </>
        ) : (
          <>
            <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 24 24">
              <path d="M12 8c-2.21 0-4 1.79-4 4s1.79 4 4 4 4-1.79 4-4-1.79-4-4-4zm8.94-3A11.93 11.93 0 0012 0C6.5 0 1.74 2.5.63 6.03c-.2.6 0 1.24.49 1.53L7 10.5c.6.41 1.42.41 2 0l6.51-4.44c.49-.29.69-.93.49-1.53C22.26 2.5 21.44 2 20.94 5z" />
            </svg>
            📍 Use My Current Location
          </>
        )}
      </button>

      {/* Instructions */}
      <div className="bg-blue-50 border-l-4 border-blue-600 p-4 rounded text-sm text-blue-800">
        <p className="font-semibold mb-1">How to select a location:</p>
        <ul className="list-disc list-inside space-y-1 text-xs">
          <li>Click anywhere on the map to pin the exact crime location</li>
          <li>Use the "Use My Current Location" button to auto-detect your location</li>
          <li>Coordinates are displayed in real-time above the map</li>
        </ul>
      </div>
    </div>
  );
};

export default LocationPicker;
